"""Format diff results as text, JSON, or CSV with glyph prefixes and summary."""

import csv
import io
import json
from typing import Dict, List, Optional, TextIO

from fsdrift.diff import Change, ChangeType


# Glyph prefixes per change type
GLYPHS: Dict[ChangeType, str] = {
    ChangeType.ADDED:     "+",
    ChangeType.REMOVED:   "-",
    ChangeType.MODIFIED:  "~",
    ChangeType.TOUCHED:   "=",
    ChangeType.MOVED:     ">",
    ChangeType.DUP_MOVED: ">>",
}


def _entry_dict(entry) -> Optional[Dict]:
    """Convert a FileEntry to a plain dict for serialization."""
    if entry is None:
        return None
    return {
        "relpath": entry.relpath,
        "size": entry.size,
        "mtime": entry.mtime,
        "sha256": entry.sha256,
        "mode": entry.mode,
    }


def _change_summary(changes: List[Change]) -> Dict[ChangeType, int]:
    """Count changes by type."""
    counts: Dict[ChangeType, int] = {ct: 0 for ct in ChangeType}
    for c in changes:
        counts[c.change_type] += 1
    return counts


def format_text(changes: List[Change], show_summary: bool = True) -> str:
    """Format changes as human-readable text with glyph prefixes.

    Each line: ``{glyph} {change_type} {detail}``
    A summary table is appended when *show_summary* is True.
    """
    lines: List[str] = []

    for c in changes:
        glyph = GLYPHS[c.change_type]
        if c.change_type == ChangeType.ADDED:
            lines.append(f"{glyph} {c.change_type.value} {c.new_entry.relpath}")
        elif c.change_type == ChangeType.REMOVED:
            lines.append(f"{glyph} {c.change_type.value} {c.old_entry.relpath}")
        elif c.change_type in (ChangeType.MODIFIED, ChangeType.TOUCHED):
            lines.append(f"{glyph} {c.change_type.value} {c.new_entry.relpath}")
        elif c.change_type in (ChangeType.MOVED, ChangeType.DUP_MOVED):
            lines.append(f"{glyph} {c.change_type.value} {c.moved_from} -> {c.moved_to}")

    if show_summary:
        counts = _change_summary(changes)
        total = sum(counts.values())
        lines.append("")
        lines.append(f"Summary: {total} change(s)")
        for ct in ChangeType:
            if counts[ct]:
                lines.append(f"  {GLYPHS[ct]} {ct.value}: {counts[ct]}")

    return "\n".join(lines) + "\n" if lines else ""


def format_json(changes: List[Change], show_summary: bool = True) -> str:
    """Format changes as a JSON object.

    The top-level object contains a ``changes`` array and optionally a
    ``summary`` object with per-type counts.
    """
    payload: Dict = {
        "changes": [
            {
                "type": c.change_type.value,
                "old": _entry_dict(c.old_entry),
                "new": _entry_dict(c.new_entry),
                "moved_from": c.moved_from,
                "moved_to": c.moved_to,
            }
            for c in changes
        ]
    }
    if show_summary:
        counts = _change_summary(changes)
        payload["summary"] = {ct.value: counts[ct] for ct in ChangeType}
    return json.dumps(payload, indent=2) + "\n"


def format_csv(changes: List[Change], show_summary: bool = True) -> str:
    """Format changes as CSV.

    Columns: type, relpath_old, relpath_new, sha256_old, sha256_new,
             size_old, size_new, mtime_old, mtime_new, moved_from, moved_to

    When *show_summary* is True, a comment block (``#``) is prepended.
    """
    buf = io.StringIO()
    writer = csv.writer(buf)

    if show_summary:
        counts = _change_summary(changes)
        total = sum(counts.values())
        buf.write(f"# Summary: {total} change(s)\n")
        for ct in ChangeType:
            if counts[ct]:
                buf.write(f"# {GLYPHS[ct]} {ct.value}: {counts[ct]}\n")

    writer.writerow([
        "type", "relpath_old", "relpath_new",
        "sha256_old", "sha256_new",
        "size_old", "size_new",
        "mtime_old", "mtime_new",
        "moved_from", "moved_to",
    ])

    for c in changes:
        old = c.old_entry
        new = c.new_entry
        writer.writerow([
            c.change_type.value,
            old.relpath if old else "",
            new.relpath if new else "",
            old.sha256 if old else "",
            new.sha256 if new else "",
            old.size if old else "",
            new.size if new else "",
            old.mtime if old else "",
            new.mtime if new else "",
            c.moved_from or "",
            c.moved_to or "",
        ])

    return buf.getvalue()


def format_output(changes: List[Change], fmt: str = "text",
                  show_summary: bool = True) -> str:
    """Dispatch to the appropriate formatter.

    Parameters
    ----------
    changes : list of Change
    fmt : "text" | "json" | "csv"
    show_summary : include a summary section
    """
    if fmt == "json":
        return format_json(changes, show_summary=show_summary)
    elif fmt == "csv":
        return format_csv(changes, show_summary=show_summary)
    else:
        return format_text(changes, show_summary=show_summary)

"""Verify a live directory against a previously captured manifest."""

from pathlib import Path
from typing import Dict, List, Tuple

from fsdrift import read_manifest, walk_tree
from fsdrift.models import FileEntry


class VerificationResult:
    """Holds the outcome of a verification run."""

    def __init__(self) -> None:
        self.added: List[FileEntry] = []
        self.removed: List[FileEntry] = []
        self.modified: List[Tuple[FileEntry, FileEntry]] = []

    @property
    def is_clean(self) -> bool:
        """True when no drift was detected."""
        return not (self.added or self.removed or self.modified)

    def __bool__(self) -> bool:
        """Drift detected → truthy."""
        return not self.is_clean


def verify(manifest_path: Path, dir_path: Path) -> VerificationResult:
    """Re-walk *dir_path* and compare against the manifest at *manifest_path*.

    Returns a ``VerificationResult`` whose ``added``, ``removed``, and
    ``modified`` lists describe any drift.
    """
    manifest_path = Path(manifest_path)
    dir_path = Path(dir_path).resolve()

    expected: List[FileEntry] = read_manifest(manifest_path)
    actual: List[FileEntry] = walk_tree(dir_path)

    expected_map: Dict[str, FileEntry] = {e.relpath: e for e in expected}
    actual_map: Dict[str, FileEntry] = {e.relpath: e for e in actual}

    result = VerificationResult()

    # Check for added or modified files
    for relpath, act in actual_map.items():
        if relpath not in expected_map:
            result.added.append(act)
        else:
            exp = expected_map[relpath]
            if (act.size != exp.size
                    or act.mtime != exp.mtime
                    or act.sha256 != exp.sha256
                    or act.mode != exp.mode):
                result.modified.append((exp, act))

    # Check for removed files
    for relpath, exp in expected_map.items():
        if relpath not in actual_map:
            result.removed.append(exp)

    return result
